 useEffect(()=>{if(!playing)return;const tick=()=>{const st=useStore.getState(),v=st.project?.videos[st.videoId];if(!v||st.frame>=v.frame_count-1){setPlaying(false);return;}if(canvas.current?.isReady())st.navigate(st.frame+1);playTimer.current=window.setTimeout(tick,Math.max(40,((ledger[st.frame+1]?.seconds??0)-(ledger[st.frame]?.seconds??0))*1000||100));};playTimer.current=window.setTimeout(tick,100);return()=>clearTimeout(playTimer.current)},[playing,ledger]);
