  if(Object.values(d.intervals).some(g=>g.identity_uuid===activeId&&g.video_id===videoId&&(g.end===null||g.end>=frame)))throw new Error('An overlapping/later gap already exists');
  for(const o of Object.values(d.observations))if(o.video_id===videoId&&o.identity_uuid===activeId&&o.frame_index>=frame&&!o.person_ext&&!o.person_visible)delete d.observations[o.id];
  if(Object.values(d.observations).some(o=>o.video_id===videoId&&o.identity_uuid===activeId&&o.frame_index>=frame))throw new Error('This person has boxes on or after this frame. Remove or move those observations before opening a gap.');
  const seg=Object.values(d.segments).find(x=>x.video_id===videoId&&x.identity_uuid===activeId&&x.end===null);
