   const mine=Object.values(d.observations).filter(o=>o.identity_uuid===activeId),other=Object.values(d.observations).filter(o=>o.identity_uuid===target);
   if(mine.some(a=>other.some(b=>a.video_id===b.video_id&&a.frame_index===b.frame_index)))throw new Error('Merge conflict: both identities have observations on the same frame');
   for(const o of mine){o.identity_uuid=target;o.review_state='draft'}
   for(const o of other)o.review_state='draft';
   for(const seg of Object.values(d.segments))if(seg.identity_uuid===activeId||seg.identity_uuid===target){seg.identity_uuid=target;seg.status='verified'}
   for(const g of Object.values(d.intervals))if(g.identity_uuid===activeId)g.identity_uuid=target;
   for(const l of Object.values(d.links)){if(l.source===activeId)l.source=target;if(l.target===activeId)l.target=target;if(l.source===l.target)delete d.links[l.id];}
   // Merge evidence is preserved in the observation notes and command history.
